import http from 'node:http';

const menu = [{ id: 1, nama: 'Kopi Susu', harga: 18000 }];
function kirimJson(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}
async function bacaJson(req) {
  let isi = '';
  for await (const p of req) isi += p;
  return JSON.parse(isi);
}
const rute = {
  'GET /menu': (req, res, url) => {
    const q = (url.searchParams.get('q') ?? '').toLowerCase();
    kirimJson(res, 200, menu.filter((m) => m.nama.toLowerCase().includes(q)));
  },
  'POST /menu': async (req, res) => {
    let data;
    try {
      data = await bacaJson(req);
    } catch {
      return kirimJson(res, 400, { error: 'JSON rusak' });
    }
    if (typeof data.nama !== 'string' || !(data.harga > 0)) {
      return kirimJson(res, 400, { error: 'nama dan harga wajib' });
    }
    const baru = { id: menu.length + 1, nama: data.nama, harga: data.harga };
    menu.push(baru);
    kirimJson(res, 201, baru);
  },
  'GET /rusak': () => {
    throw new Error('bug di penangan');
  },
};
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const penangan = rute[`${req.method} ${url.pathname}`];
  if (!penangan) return kirimJson(res, 404, { error: 'Tidak ditemukan' });
  try {
    await penangan(req, res, url);
  } catch (e) {
    kirimJson(res, 500, { error: 'Terjadi kesalahan di server' });
  }
});
server.listen(3000);

const u = 'http://localhost:3000';
const post = (body) => fetch(u + '/menu', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
console.log((await post({ nama: 'Es Kopi', harga: 15000 })).status);
console.log((await post({ nama: 'Gratis', harga: 0 })).status);
console.log((await (await fetch(u + '/menu?q=kopi')).json()).length);
console.log((await fetch(u + '/rusak')).status);
server.close();

